'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const KEY='neuroforge.data.v2',OLD='neuroforge.v1.sessions',USER_KEY='neuroforge.data.v2.user.';
