{id:'people-context',name:'People & Context',area:'People Skills',description:'Remember fictional details and interpret social situations carefully.',activities:['tone','profiles','expressions','conversations','profiles','tone','conversations','expressions','profiles','conversations','tone','expressions']},
{id:'reasoning-lab',name:'Reasoning Lab',area:'Intelligence',description:'Discover rules, combine patterns and solve multi-step problems.',activities:['switch','logic','weave','logiclab','weave','switch','logiclab','logic','weave','logiclab','switch','logic']},
{id:'wayfinding',name:'Spatial Wayfinding',area:'Navigation',description:'Build route memory, orientation and spatial transformation skills.',activities:['spatial','rotate','route','landmark','route','spatial','landmark','rotate','route','landmark','spatial','rotate']},
{id:'balanced-mind',name:'Balanced Training Course',area:'All domains',description:'A twelve-session rotation through all six training domains.',activities:['focus','sequence','reaction','tone','logic','route','peripheral','scene','compare','profiles','weave','landmark']}
