const id=()=>window.crypto?.randomUUID?.()||'nf-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
function load(storageKey=KEY){try{const s=JSON.parse(localStorage.getItem(storageKey)||'null');if(s?.version===2)return {...s,sessions:Array.isArray(s.sessions)?s.sessions:[],profile:s.profile||{name:'Guest athlete',goal:10}};const old=storageKey===KEY?JSON.parse(localStorage.getItem(OLD)||'[]'):[];return {version:2,sessions:Array.isArray(old)?old.map(x=>({id:id(),activityId:x.id||'sequence',activityName:x.name||'Earlier session',area:'Memory',level:1,accuracy:+x.accuracy||0,durationSeconds:+x.duration||0,correct:0,items:0,metrics:{migrated:true},completedAt:+x.timestamp||Date.now()})):[],profile:{name:'Guest athlete',goal:10}};}catch{return {version:2,sessions:[],profile:{name:'Guest athlete',goal:10}};}}
let S=load(KEY),activeStorageKey=KEY,cloud=null,user=null,current=null,level=1,runDifficulty=1,challengeStage=0,round=0,scores=[],D=null,timer=null,queue=[],plan='balanced',source='single',filter='All',authMode='signin',planTotal=3,planDone=0,searchQuery='',customSelection=new Set(),adaptiveTrace=[],strongRun=0,weakRun=0,activeCourseId=null,courseStepInProgress=0,courseReviewMode=false,mapSelectedActivity='sequence',mapSelectedLevel=1,audioContext=null;
function switchDataSpace(nextUser,carryGuest=false){const nextKey=nextUser?USER_KEY+nextUser.id:KEY;if(nextKey===activeStorageKey)return;save();activeStorageKey=nextKey;const existing=localStorage.getItem(nextKey);if(existing){S=load(nextKey);}else if(nextUser&&carryGuest){const guest=load(KEY);S={version:2,sessions:[...guest.sessions],profile:{...guest.profile}};}else if(nextUser){S={version:2,sessions:[],profile:{name:'Guest athlete',goal:10}};}else{S=load(KEY);}save();}
const save=()=>{try{localStorage.setItem(activeStorageKey,JSON.stringify(S));}catch{toast('Storage is full. Export your data.');}};
const toast=m=>{const e=$('#toast');e.textContent=m;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),2400);};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const activity=id=>A.find(a=>a.id===id);
const history=id=>S.sessions.filter(s=>s.activityId===id);
function progressionFor(id){const engine=window.NeuroForgeProgression;return engine?engine.getProgression(history(id)):{level:1,stage:0,reason:'Complete a few sessions to calibrate this activity.'};}
function levelFor(id){return progressionFor(id).level;}
function overloadFor(id){return progressionFor(id).stage;}
function progressionLabel(id){const p=progressionFor(id);return 'Level '+p.level+' · Stage '+(p.stage+1)+'/5';}
const dayKey=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
function streak(){const set=new Set(S.sessions.map(s=>dayKey(new Date(s.completedAt))));let d=new Date();if(!set.has(dayKey(d)))d.setDate(d.getDate()-1);let n=0;while(set.has(dayKey(d))){n++;d.setDate(d.getDate()-1);}return n;}
function mean(rows){return rows.length?Math.round(rows.reduce((n,s)=>n+s.accuracy,0)/rows.length):0;}
function card(a){return '<article class="activity-card"><div class="activity-top"><span class="activity-symbol">'+a.symbol+'</span><span class="activity-category">'+a.area.toUpperCase()+'</span></div><h3>'+a.name+'</h3><p>'+a.description+'</p><div class="activity-footer"><span>'+a.minutes+' min · <span class="activity-level">'+progressionLabel(a.id)+'</span> · '+history(a.id).length+' played</span><div class="activity-actions"><button class="preview-action" data-preview="'+a.id+'">Preview</button><button data-play="'+a.id+'">Train →</button></div></div></article>'; }
function recommendedActivities(){return DOMAINS.map(domain=>A.filter(a=>a.area===domain.name).map(a=>{const rows=history(a.id),recent=[...rows].sort((x,y)=>y.completedAt-x.completedAt).slice(0,3),avg=recent.length?mean(recent):65,last=rows.length?Math.max(0,(Date.now()-Math.max(...rows.map(x=>x.completedAt)))/86400000):14;return {id:a.id,priority:last*.12+(100-avg)*.055+1/(1+rows.length)*2};}).sort((x,y)=>y.priority-x.priority)[0].id);}
function renderCards(){const q=searchQuery.trim().toLowerCase();$('#suggested-activities').innerHTML=recommendedActivities().slice(0,4).map(x=>card(activity(x))).join('');$('#library-activities').innerHTML=A.filter(a=>(filter==='All'||a.area===filter)&&(!q||(a.name+' '+a.area+' '+a.description).toLowerCase().includes(q))).map(card).join('');}
function renderCourses(){const host=$('#course-library');if(!host)return;host.innerHTML=COURSES.map(course=>{const done=S.sessions.filter(s=>(s.courseId||s.metrics?.courseId)===course.id).length,shown=Math.min(done,course.activities.length),percent=Math.round(shown/course.activities.length*100),complete=done>=course.activities.length;return '<article class=\"course-card\"><div class=\"course-top\"><span>'+escape(course.area)+'</span><span>'+shown+'/'+course.activities.length+' sessions</span></div><h3>'+escape(course.name)+'</h3><p>'+escape(course.description)+'</p><div class=\"course-progress\"><span style=\"width:'+percent+'%\"></span></div><div class=\"course-bottom\"><small>'+percent+'% complete · '+(complete?'Completed':'Self-paced course')+'</small><button class=\"button '+(complete?'secondary':'primary')+'\" data-course-start=\"'+course.id+'\">'+(complete?'Review course':'Continue course')+' →</button></div></article>';}).join('');}
function renderCustomPlan(){const host=$('#custom-activity-list');if(!host)return;host.innerHTML=A.map(a=>'<label class="custom-activity"><input type="checkbox" data-custom-activity="'+a.id+'" '+(customSelection.has(a.id)?'checked':'')+'><span>'+escape(a.name)+'</span><small>'+escape(a.area)+'</small></label>').join('');updateCustomCount();}
function updateCustomCount(){const n=customSelection.size;$('#custom-count').textContent=n+' of 8 activities selected';$('#start-custom-plan').disabled=n===0;}
function renderHome(){const start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-6);const week=S.sessions.filter(x=>x.completedAt>=start.getTime());const today=new Date();today.setHours(0,0,0,0);const todaySeconds=S.sessions.filter(x=>x.completedAt>=today.getTime()).reduce((n,x)=>n+x.durationSeconds,0);const goal=Math.max(1,Number(S.profile.goal)||10),todayMinutes=Math.round(todaySeconds/60*10)/10,percent=Math.min(100,Math.round(todaySeconds/(goal*60)*100));$('#today-date').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'});$('#metric-minutes').textContent=Math.round(week.reduce((n,x)=>n+x.durationSeconds,0)/60);$('#metric-sessions').textContent=S.sessions.length;$('#metric-streak').textContent=streak()+' days';$('#metric-accuracy').textContent=S.sessions.length?mean(S.sessions)+'%':'—';$('#today-goal-label').textContent=todayMinutes+' / '+goal+' min';$('#today-goal-fill').style.width=percent+'%';$('.daily-goal-track').setAttribute('aria-valuenow',String(percent));$('#today-goal-copy').textContent=percent>=100?'Daily target reached. You practiced '+todayMinutes+' minutes today.':Math.max(0,Math.ceil(goal-todayMinutes))+' minutes left to reach your daily target. You can change it in Settings.';const name=S.profile.name||'Guest athlete';$('#sidebar-name').textContent=name;$('#avatar').textContent=name.charAt(0).toUpperCase();$('#top-avatar').textContent=$('#avatar').textContent;$('#display-name').value=name;$('#daily-goal').value=String(S.profile.goal||10);renderCards();}
function view(name){clearTimeout(timer);$$('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+name));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='progress')renderProgress();if(name==='plans')renderCourses();if(name==='settings')renderSettings();scrollTo({top:0,behavior:'smooth'});}
function renderSettings(){const online=!!user;$('#cloud-description').textContent=online?'Signed in. Cloud sync is active.':'Cloud sync is optional and not connected.';$('#sync-indicator').textContent=online?'SYNCED':'LOCAL';$('#account-status').textContent=online?'Signed in as '+user.email+'. Session history is synchronized.':'Your sessions are saved in this browser. A Supabase project URL and publishable key are needed for cross-device sync.';$('#sidebar-sync').textContent=online?'Cloud sync active':'Saved on this device';$('#top-status').textContent=online?'Cloud account connected':'Personal training space';$('#account-label').textContent=online?user.email:'Guest account';}
function renderProgress(){const dates=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));return d;}),mins=dates.map(d=>S.sessions.filter(s=>dayKey(new Date(s.completedAt))===dayKey(d)).reduce((n,s)=>n+s.durationSeconds,0)/60),max=Math.max(1,...mins);$('#weekly-chart').innerHTML=dates.map((d,i)=>'<div class="bar-column"><em>'+(mins[i]?Math.round(mins[i])+'m':'')+'</em><div class="bar" style="height:'+Math.max(3,mins[i]/max*125)+'px"></div><small>'+d.toLocaleDateString(undefined,{weekday:'short'})+'</small></div>').join('');$('#skill-breakdown').innerHTML=DOMAINS.map(domain=>{const ids=A.filter(a=>a.area===domain.name).map(a=>a.id),n=S.sessions.filter(s=>ids.includes(s.activityId)||(!s.activityId&&window.NeuroForgeCatalog.areaForSession(s)===domain.name)).length;return '<div class=\"break-row\"><span class=\"break-name\">'+domain.name+'</span><div class=\"break-track\"><div class=\"break-fill\" style=\"width:'+(S.sessions.length?n/Math.max(1,S.sessions.length)*100:0)+'%\"></div></div><span class=\"break-count\">'+n+'</span></div>';}).join('');renderLevelMap();$('#activity-performance').innerHTML='<table class="perf-table"><thead><tr><th>ACTIVITY</th><th>SESSIONS</th><th>AVERAGE</th><th>BEST</th><th>PROGRESSION</th></tr></thead><tbody>'+A.map(a=>{const rows=history(a.id);return '<tr><td>'+a.name+'<span class="table-sub">'+a.area+'</span></td><td>'+rows.length+'</td><td>'+(rows.length?mean(rows)+'%':'—')+'</td><td>'+(rows.length?Math.max(...rows.map(x=>x.accuracy))+'%':'—')+'</td><td>'+progressionLabel(a.id)+'</td></tr>';}).join('')+'</tbody></table>';const recent=[...S.sessions].sort((a,b)=>b.completedAt-a.completedAt).slice(0,12);$('#session-history').innerHTML=recent.length?recent.map(s=>'<div class="history-row"><div>'+escape(s.activityName)+'<small>'+new Date(s.completedAt).toLocaleString()+' · '+s.durationSeconds+' sec · Level '+s.level+' · Stage '+(Number(s.metrics?.challengeStage||0)+1)+'/5</small></div><span class="history-score">'+s.accuracy+'%</span></div>').join(''):'<div class="empty-state">No sessions yet. Complete an activity to see your history.</div>';const trend=[...S.sessions].sort((a,b)=>a.completedAt-b.completedAt).slice(-10);$('#accuracy-trend').innerHTML=trend.length?'<div class="trend-bars">'+trend.map(s=>'<div class="trend-column" title="'+escape(s.activityName)+' · '+s.accuracy+'%"><strong>'+s.accuracy+'%</strong><div class="trend-track"><div class="trend-fill" style="height:'+Math.max(2,Math.min(100,s.accuracy))+'%"></div></div><small>'+escape(s.activityName.slice(0,9))+'</small></div>').join('')+'</div><p class="fine-print">Latest '+trend.length+' completed sessions. These scores measure activity performance only.</p>':'<div class="empty-state">Complete activities to build your accuracy trend.</div>';const played=A.map(a=>({a,rows:history(a.id)})).filter(x=>x.rows.length).sort((x,y)=>mean(x.rows.slice(-3))-mean(y.rows.slice(-3))).slice(0,3);$('#progression-insight').innerHTML=played.length?played.map(({a,rows})=>'<div class="insight-row"><div><strong>'+a.name+'</strong><small>'+a.area+' · '+rows.length+' session'+(rows.length===1?'':'s')+'</small></div><span>'+mean(rows.slice(-3))+'% recent</span></div><p class="insight-reason">'+escape(progressionFor(a.id).reason)+'</p>').join(''):'<div class="empty-state">Start with any activity. Your recommendations will appear here after you have training history.</div>';}
function previewLevelDescription(activityId,requestedLevel){const l=Math.max(1,Math.min(10,Number(requestedLevel)||1));switch(activityId){case'sequence':return 'Sequence length: '+Math.min(10,3+Math.floor((l-1)/2))+' tiles. Presentation pace tightens as the challenge tier rises.';case'pattern':return 'Remember '+Math.min(10,3+Math.floor(l/2))+' highlighted locations in a 4 × 4 grid.';case'words':return 'Study '+Math.min(12,4+Math.floor(l/2))+' words, then recognize them among alternatives.';case'nback':return 'Memory lag: '+Math.min(4,2+Math.floor((l-1)/4))+' items. Compare each symbol with the required earlier position.';case'focus':return 'Target count: '+Math.min(12,3+Math.floor(l/2))+' among '+(24+Math.floor((l-1)*1.2))+' symbols.';case'spatial':return 'Remember '+Math.min(10,3+Math.floor(l/2))+' directional steps before reproducing the path.';case'route':return 'Map size: '+(l>=7?'5 × 5':'4 × 4')+'. Recall '+Math.min((l>=7?25:16)-1,3+Math.floor((l-1)/3))+' consecutive locations.';case'tones':return 'Listen for '+Math.min(8,3+Math.floor(l/2))+' synthesized tones and replay the order.';case'scene':return 'Study a scene containing '+Math.min(8,4+Math.floor(l/2))+' objects, then locate a selected object.';case'compare':return 'Compare two symbol strings containing '+Math.min(12,4+l)+' positions.';case'sweep':return 'Scan a field of '+Math.min(72,24+l*3)+' symbols and count the target.';default:return 'Level '+l+' of 10. Each level uses a different starting challenge; the in-session staircase can adjust difficulty as you play.';}}
function openExercisePreview(activityId,requestedLevel=null){const a=activity(activityId);if(!a)return;const levelValue=Math.max(1,Math.min(10,Number(requestedLevel)||progressionFor(activityId).level));$('#preview-title').textContent=a.name;$('#preview-domain').textContent=a.area.toUpperCase()+' · '+a.minutes+' MIN';$('#preview-description').textContent=a.description;$('#preview-level').value=String(levelValue);$('#preview-challenge').textContent=previewLevelDescription(activityId,levelValue);const st=levelStats(activityId,levelValue);$('#preview-history').innerHTML='<div><strong>'+(st.baseline===null?'—':st.baseline+'%')+'</strong><small>Baseline</small></div><div><strong>'+(st.best===null?'—':st.best+'%')+'</strong><small>Best</small></div><div><strong>'+(st.average===null?'—':st.average+'%')+'</strong><small>Average</small></div><div><strong>'+st.attempts+'</strong><small>Attempts</small></div>';$('#preview-start').dataset.activityId=activityId;const dialog=$('#exercise-preview-dialog');if(!dialog.open)dialog.showModal();}
function levelStats(activityId,requestedLevel){const rows=history(activityId).filter(s=>Number(s.level)===Number(requestedLevel)).sort((x,y)=>x.completedAt-y.completedAt);if(!rows.length)return {rows,baseline:null,best:null,average:null,attempts:0};const vals=rows.map(x=>Number(x.accuracy)||0);return {rows,baseline:vals[0],best:Math.max(...vals),average:Math.round(vals.reduce((sum,x)=>sum+x,0)/vals.length),attempts:vals.length};}
function renderLevelMap(){const host=$('#exercise-level-map');if(!host)return;host.innerHTML=DOMAINS.map(domain=>{const group=A.filter(a=>a.area===domain.name);return '<section class=\"map-domain\"><div class=\"map-domain-heading\"><strong>'+domain.name+'</strong><span>'+group.reduce((n,a)=>n+history(a.id).length,0)+' sessions</span></div>'+group.map(a=>'<div class=\"map-exercise-row\"><div class=\"map-exercise-name\"><strong>'+escape(a.name)+'</strong><small>'+history(a.id).length+' attempts</small></div><div class=\"map-levels\">'+Array.from({length:10},(_,i)=>{const l=i+1,st=levelStats(a.id,l),tier=st.attempts?(st.best>=90?'mastered':st.best>=70?'practiced':'started'):'empty',selected=a.id===mapSelectedActivity&&l===mapSelectedLevel;return '<button class=\"map-level '+tier+(selected?' selected':'')+'\" data-map-level=\"'+l+'\" data-map-activity=\"'+a.id+'\" title=\"'+escape(a.name)+' · Level '+l+' · '+(st.attempts?st.attempts+' attempts, best '+st.best+'%':'Not played yet')+'\" aria-label=\"'+escape(a.name)+' level '+l+'\">'+l+'</button>';}).join('')+'</div></div>').join('')+'</section>';}).join('');const selected=activity(mapSelectedActivity)||A[0],st=levelStats(selected.id,mapSelectedLevel);$('#level-detail').innerHTML='<div class=\"level-detail-title\"><div><small>'+selected.area.toUpperCase()+' · LEVEL '+mapSelectedLevel+'</small><h3>'+escape(selected.name)+'</h3></div><button class=\"button primary\" data-map-preview=\"'+selected.id+'\" data-map-preview-level=\"'+mapSelectedLevel+'\">Preview this level →</button></div><div class=\"level-stat-grid\"><div><strong>'+(st.baseline===null?'—':st.baseline+'%')+'</strong><small>Baseline</small></div><div><strong>'+(st.best===null?'—':st.best+'%')+'</strong><small>Best</small></div><div><strong>'+(st.average===null?'—':st.average+'%')+'</strong><small>Average</small></div><div><strong>'+st.attempts+'</strong><small>Attempts</small></div></div><p class=\"fine-print\">Baseline is your first recorded score at this level. Best and average are your own results, not population percentiles.</p>';}
function exportData(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),product:'NeuroForge',data:S},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='neuroforge-data-'+dayKey(new Date())+'.json';a.click();URL.revokeObjectURL(url);toast('Your data export is ready.');}
function normalizeImportedSession(raw){if(!raw||typeof raw!=='object')return null;const a=activity(String(raw.activityId||'')),accuracy=Number(raw.accuracy),completedAt=Number(raw.completedAt);if(!a||!Number.isFinite(accuracy)||accuracy<0||accuracy>100||!Number.isFinite(completedAt)||completedAt<=0)return null;const bounded=(v,min,max)=>Math.max(min,Math.min(max,Number(v)||min)),m=raw.metrics&&typeof raw.metrics==='object'?raw.metrics:{};return {id:String(raw.id||id()).slice(0,120),activityId:a.id,activityName:a.name,area:a.area,level:bounded(raw.level,1,10),accuracy,durationSeconds:bounded(raw.durationSeconds,0,86400),correct:bounded(raw.correct,0,10000),items:bounded(raw.items,0,10000),metrics:{roundScores:Array.isArray(m.roundScores)?m.roundScores.slice(0,20).map(x=>bounded(x,0,100)):[],challengeStage:bounded(m.challengeStage,0,4),runDifficultyStart:bounded(m.runDifficultyStart,1,10),runDifficultyEnd:bounded(m.runDifficultyEnd,1,10),adaptiveTrace:Array.isArray(m.adaptiveTrace)?m.adaptiveTrace.slice(0,20).map(x=>bounded(x,1,10)):[],courseId:typeof m.courseId==='string'?m.courseId:null,courseStep:m.courseStep==null?null:bounded(m.courseStep,0,100),averageReactionMs:m.averageReactionMs==null?null:bounded(m.averageReactionMs,0,10000)},courseId:typeof raw.courseId==='string'?raw.courseId:(typeof m.courseId==='string'?m.courseId:null),courseStep:raw.courseStep==null?(m.courseStep==null?null:bounded(m.courseStep,0,100)):bounded(raw.courseStep,0,100),completedAt};}
async function importDataFile(file){if(!file)return;if(file.size>5*1024*1024)throw new Error('Backup files must be 5 MB or smaller.');const parsed=JSON.parse(await file.text()),data=parsed?.data||parsed;if(data?.version!==2||!Array.isArray(data.sessions))throw new Error('This is not a valid NeuroForge version 2 backup.');const incoming=data.sessions.map(normalizeImportedSession).filter(Boolean);if(!incoming.length)throw new Error('No valid NeuroForge sessions were found in this backup.');const merged=new Map(S.sessions.map(s=>[s.id,s]));let added=0;incoming.forEach(s=>{if(!merged.has(s.id)){merged.set(s.id,s);added++;}});S.sessions=[...merged.values()].sort((a,b)=>a.completedAt-b.completedAt).slice(-1500);save();renderHome();renderProgress();toast('Imported '+added+' new session records. Existing records were preserved.');}
function startPlan(name){plan=name;queue=[...(PLANS[name]||PLANS.balanced)];planTotal=queue.length;planDone=0;activeCourseId=null;source='plan';nextPlan();}
function startPersonalTrainer(){plan='personal';queue=recommendedActivities();planTotal=queue.length;planDone=0;activeCourseId=null;source='plan';nextPlan();}
function startCourse(courseId){const course=COURSES.find(x=>x.id===courseId);if(!course)return;const done=S.sessions.filter(s=>(s.courseId||s.metrics?.courseId)===courseId).length;activeCourseId=courseId;courseReviewMode=done>=course.activities.length;courseStepInProgress=courseReviewMode?0:done;source='course';plan='course';planTotal=course.activities.length;planDone=courseStepInProgress+1;queue=[];begin(course.activities[courseStepInProgress]);$('#game-tip').textContent=course.name+' · Session '+(courseStepInProgress+1)+' of '+course.activities.length+(courseReviewMode?' · Review':'');}

function nextPlan(){if(!queue.length){source='single';toast('Training plan completed.');view('home');return;}planDone++;begin(queue.shift());$('#game-tip').textContent='Plan: '+(plan==='custom'?'Custom session':plan)+' · '+planDone+' of '+planTotal+' activities';}
