function score(){if(!D)return 0;switch(current.id){case'sequence':return D.ready&&D.seq.length?D.sel.reduce((n,v,i)=>n+(v===D.seq[i]?1:0),0)/D.seq.length:0;case'pattern':case'words':return D.ready?f1(D.target,D.sel):0;case'spatial':return D.ready?D.sel.reduce((n,v,i)=>n+(v===D.seq[i]?1:0),0)/D.seq.length:0;case'nback':return D.responses.length===D.expected.length?D.expected.reduce((n,v,i)=>n+(v===D.responses[i]?1:0),0)/D.expected.length:0;case'focus':case'dual':return f1(D.target,D.sel);case'route':case'tones':return D.ready&&D.seq.length?D.sel.reduce((n,v,i)=>n+(v===D.seq[i]?1:0),0)/D.seq.length:0;case'tone':case'search':case'stroop':case'rotate':case'scene':case'tasks':case'peripheral':case'compare':case'pitch':case'sweep':case'profiles':case'expressions':case'conversations':case'weave':case'logiclab':case'landmark':return D.answer===D.correct?1:0;case'reaction':return !D.falseStart&&D.ms!==null?(D.ms<=D.reactionLimitMs?1:D.ms<=D.reactionLimitMs*1.6?.5:0):0;case'math':case'switch':case'logic':return D.answer===D.correct?1:0;default:return 0;}}
function submitRound(){if(!D)return;let complete=false;switch(current.id){case'sequence':case'spatial':case'route':case'tones':complete=!!D.ready&&D.sel.length===D.seq.length;break;case'pattern':case'words':complete=!!D.ready&&D.sel.length>0;break;case'focus':case'dual':complete=D.sel.length>0;break;case'nback':complete=D.responses.length===D.expected.length;break;case'reaction':complete=D.status==='done';break;default:complete=D.answer!==null&&D.answer!==undefined;}if(!complete){toast('Finish the round before submitting.');return;}const result=score();scores.push(result);if(result>=.85){strongRun++;weakRun=0;if(strongRun>=2&&runDifficulty<10){runDifficulty++;strongRun=0;adaptiveTrace.push(runDifficulty);toast('Challenge increased to '+runDifficulty+'/10.');}}else if(result<.5){weakRun++;strongRun=0;if(weakRun>=2&&runDifficulty>1){runDifficulty--;weakRun=0;adaptiveTrace.push(runDifficulty);toast('Challenge eased to '+runDifficulty+'/10.');}}else{strongRun=0;weakRun=0;}$('#game-level').textContent='Level '+level+' · adaptive challenge '+runDifficulty+'/10';if(current.id==='reaction'&&D.ms!==null)scores.reactionMs=(scores.reactionMs||[]).concat(D.ms);$('#game-live-feedback').textContent=result>=.8?'Strong round · '+Math.round(result*100)+'%':result>=.5?'Round recorded · '+Math.round(result*100)+'%':'Keep practicing · '+Math.round(result*100)+'%';$('#game-submit').disabled=true;$('#game-start').disabled=false;$('#game-start').textContent=round>=5?'Finish session':'Next round';$('#game-progress-fill').style.width=(round*20)+'%';$$('.tile,.choice-button,.reaction-pad,.dual-choice,.rotation-option').forEach(b=>b.disabled=true);D=null;if(round>=5)timer=setTimeout(finish,450);}
function finish(){clearTimeout(timer);const accuracy=Math.round(scores.reduce((a,b)=>a+b,0)/Math.max(1,scores.length)*100),seconds=Math.max(1,Math.round((Date.now()-current.started)/1000)),rt=scores.reactionMs||[],s={id:id(),activityId:current.id,activityName:current.name,area:current.area,level,accuracy,durationSeconds:seconds,courseId:activeCourseId,courseStep:activeCourseId?courseStepInProgress:null,correct:Math.round(scores.reduce((a,b)=>a+b,0)),items:scores.length,metrics:{roundScores:scores.map(x=>Math.round(x*100)),challengeStage,runDifficultyStart:level,runDifficultyEnd:runDifficulty,adaptiveTrace:[...adaptiveTrace],courseId:activeCourseId,courseStep:activeCourseId?courseStepInProgress:null,averageReactionMs:rt.length?Math.round(rt.reduce((a,b)=>a+b,0)/rt.length):null},completedAt:Date.now()};S.sessions.push(s);S.sessions=S.sessions.slice(-1500);save();syncSession(s);const nextProgress=progressionFor(current.id),next=nextProgress.level;$('#summary-title').textContent=accuracy>=85?'Excellent consistency.':accuracy>=60?'Session complete.':'Practice is progress.';$('#summary-copy').textContent='You completed '+current.name+'. Your activity score has been saved.';$('#summary-symbol').textContent=accuracy>=60?'✓':'↗';$('#summary-metrics').innerHTML='<div><strong>'+accuracy+'%</strong><small>Activity accuracy</small></div><div><strong>'+seconds+'s</strong><small>Time practiced</small></div><div><strong>Level '+next+' · '+(nextProgress.stage+1)+'/5</strong><small>Next challenge</small></div>';$('#summary-note').textContent=nextProgress.reason;$('#summary-next').textContent=source==='plan'?(queue.length?'Next plan activity →':'Finish plan →'):source==='course'?'Next course session →':'Browse activities →';renderHome();view('summary');}
function continueSummary(){if(source==='plan'&&queue.length){nextPlan();return;}if(source==='plan'){source='single';toast('You completed your training plan.');view('home');return;}if(source==='course'&&activeCourseId){const course=COURSES.find(x=>x.id===activeCourseId),done=S.sessions.filter(s=>(s.courseId||s.metrics?.courseId)===activeCourseId).length;if(course&&courseReviewMode&&courseStepInProgress+1<course.activities.length){courseStepInProgress++;begin(course.activities[courseStepInProgress]);$('#game-tip').textContent=course.name+' · Session '+(courseStepInProgress+1)+' of '+course.activities.length+' · Review';return;}if(course&&!courseReviewMode&&done<course.activities.length){startCourse(activeCourseId);return;}activeCourseId=null;courseReviewMode=false;source='single';toast('Course completed.');view('plans');return;}view('training');}
function openAccount(){const dlg=$('#account-dialog');if(!cloud){$('#auth-title').textContent='Cloud connection unavailable';$('#auth-copy').textContent='NeuroForge could not connect to its cloud service. Your local progress remains available in this browser.';$('#auth-form').hidden=true;$('#auth-toggle').hidden=true;$('#auth-signout').hidden=true;$('#auth-message').textContent='Check your connection and try again later.';}else if(user){$('#auth-title').textContent='Your NeuroForge account';$('#auth-copy').textContent='Signed in as '+(user.email||'your account')+'. Completed sessions sync to your account.';$('#auth-form').hidden=true;$('#auth-toggle').hidden=true;$('#auth-signout').hidden=false;$('#auth-message').textContent='Signing out returns this browser to guest mode. Your cloud history remains in your account.';}else{$('#auth-title').textContent=authMode==='signin'?'Sign in to NeuroForge':'Create your NeuroForge account';$('#auth-copy').textContent='Synchronize your practice history across devices.';$('#auth-form').hidden=false;$('#auth-toggle').hidden=false;$('#auth-signout').hidden=true;$('#auth-submit').textContent=authMode==='signin'?'Sign in':'Create account';$('#auth-toggle').textContent=authMode==='signin'?'Create a new account':'I already have an account';}dlg.showModal();}
async function setupCloud(){const c=window.NEUROFORGE_CONFIG||{};if(!c.supabaseUrl||!c.supabasePublishableKey||!window.supabase?.createClient)return;try{cloud=window.supabase.createClient(c.supabaseUrl,c.supabasePublishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const {data}=await cloud.auth.getSession();user=data.session?.user||null;cloud.auth.onAuthStateChange((_e,session)=>{const nextUser=session?.user||null;switchDataSpace(nextUser,!user&&!!nextUser);user=nextUser;renderHome();renderSettings();if(user)Promise.resolve().then(pullCloud);});switchDataSpace(user);renderSettings();if(user)await pullCloud();}catch(e){console.error('Cloud initialization failed',e);cloud=null;renderSettings();}}
async function authSubmit(e){e.preventDefault();if(!cloud)return;const email=$('#auth-email').value.trim(),password=$('#auth-password').value;$('#auth-submit').disabled=true;try{const r=authMode==='signin'?await cloud.auth.signInWithPassword({email,password}):await cloud.auth.signUp({email,password,options:{emailRedirectTo:new URL('./',location.href).href}});if(r.error)throw r.error;if(authMode==='signup'&&!r.data.session){$('#auth-message').textContent='Check your email for a confirmation link before signing in.';return;}user=r.data.user||r.data.session?.user||null;if(user){switchDataSpace(user,!activeStorageKey.startsWith(USER_KEY));await pullCloud();$('#account-dialog').close();toast('Account connected.');renderHome();renderSettings();}}catch(err){$('#auth-message').textContent=err.message||'Sign-in failed. Please try again.';}finally{$('#auth-submit').disabled=false;}}
function cloudRow(s){return {id:s.id,user_id:user.id,activity_id:s.activityId,activity_name:s.activityName,area:s.area,level:s.level,accuracy:s.accuracy,duration_seconds:s.durationSeconds,correct_count:s.correct,item_count:s.items,metrics:s.metrics||{},completed_at:new Date(s.completedAt).toISOString()};}
async function syncSession(s){if(!cloud||!user)return;const {error}=await cloud.from('training_sessions').upsert(cloudRow(s),{onConflict:'id',ignoreDuplicates:true});if(error)console.warn('Cloud sync issue:',error.message);}
async function pullCloud(){if(!cloud||!user)return;try{const {data,error}=await cloud.from('training_sessions').select('*').order('completed_at',{ascending:false}).limit(1000);if(error)throw error;const map=new Map(S.sessions.map(s=>[s.id,s]));(data||[]).forEach(r=>map.set(r.id,{id:r.id,activityId:r.activity_id,activityName:r.activity_name,area:r.area,level:r.level,accuracy:r.accuracy,durationSeconds:r.duration_seconds,correct:r.correct_count,items:r.item_count,metrics:r.metrics||{},completedAt:new Date(r.completed_at).getTime()}));S.sessions=[...map.values()].sort((a,b)=>a.completedAt-b.completedAt).slice(-1500);save();renderHome();renderSettings();}catch(err){console.warn('Cloud sync unavailable:',err.message);toast('Cloud sync issue. Local progress is still saved.');}}
document.addEventListener('click',e=>{const p=e.target.closest('[data-play]'),pv=e.target.closest('[data-preview]'),g=e.target.closest('[data-go]'),t=e.target.closest('[data-plan]'),c=e.target.closest('[data-course-start]'),m=e.target.closest('[data-map-level]'),mp=e.target.closest('[data-map-preview]');if(p){source='single';activeCourseId=null;queue=[];begin(p.dataset.play);}if(pv)openExercisePreview(pv.dataset.preview);if(g)view(g.dataset.go);if(t)startPlan(t.dataset.plan);if(c)startCourse(c.dataset.courseStart);if(m){mapSelectedActivity=m.dataset.mapActivity;mapSelectedLevel=Number(m.dataset.mapLevel);renderLevelMap();}if(mp)openExercisePreview(mp.dataset.mapPreview,Number(mp.dataset.mapPreviewLevel));});
document.addEventListener('change',e=>{const box=e.target.closest('[data-custom-activity]');if(!box)return;if(box.checked&&customSelection.size>=8){box.checked=false;toast('Choose up to 8 activities per custom session.');return;}if(box.checked)customSelection.add(box.dataset.customActivity);else customSelection.delete(box.dataset.customActivity);updateCustomCount();});
$$('.nav-item').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));
$$('.filter-chip').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;$$('.filter-chip').forEach(x=>x.classList.toggle('selected',x===b));renderCards();}));
$('#activity-search').addEventListener('input',e=>{searchQuery=e.target.value;renderCards();});
$('#start-custom-plan').addEventListener('click',()=>{const selected=A.filter(a=>customSelection.has(a.id)).map(a=>a.id);if(!selected.length){toast('Choose at least one activity first.');return;}plan='custom';queue=selected.slice();planTotal=queue.length;planDone=0;source='plan';nextPlan();});
$('#import-data-button').addEventListener('click',()=>$('#import-data').click());
$('#import-data').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{await importDataFile(file);}catch(err){toast(err.message||'Import failed.');}finally{e.target.value='';}});
$('#start-daily').addEventListener('click',startPersonalTrainer);
$('#preview-level').addEventListener('change',()=>{const id=$('#preview-start').dataset.activityId;openExercisePreview(id,Number($('#preview-level').value));});
$('#preview-start').addEventListener('click',()=>{const id=$('#preview-start').dataset.activityId,levelValue=Number($('#preview-level').value);$('#exercise-preview-dialog').close();source='single';activeCourseId=null;queue=[];begin(id,levelValue);});
$('#game-start').addEventListener('click',startRound);$('#game-submit').addEventListener('click',submitRound);
$('#exit-game').addEventListener('click',()=>{clearTimeout(timer);source='single';activeCourseId=null;queue=[];view('training');});
$('#summary-next').addEventListener('click',continueSummary);$('#summary-home').addEventListener('click',()=>{source='single';queue=[];view('home');});
$('#export-data').addEventListener('click',exportData);$('#export-settings').addEventListener('click',exportData);
$('#save-profile').addEventListener('click',()=>{S.profile.name=$('#display-name').value.trim().slice(0,32)||'Guest athlete';S.profile.goal=Number($('#daily-goal').value)||10;save();renderHome();toast('Preferences saved.');});
$('#clear-data').addEventListener('click',()=>{if(confirm('Permanently clear activity history saved in this browser? Export it first if you want a copy.')){S.sessions=[];save();renderHome();renderProgress();toast('Local history cleared.');}});
$('#account-button').addEventListener('click',openAccount);$('#settings-account').addEventListener('click',openAccount);
$('#auth-form').addEventListener('submit',authSubmit);$('#auth-toggle').addEventListener('click',()=>{authMode=authMode==='signin'?'signup':'signin';openAccount();});$('#auth-signout').addEventListener('click',signOutAccount);
renderHome();renderProgress();renderSettings();renderCustomPlan();renderCourses();setupCloud();
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js').catch(e=>console.warn('Offline cache unavailable',e));
async function signOutAccount(){if(!cloud||!user)return;$('#auth-signout').disabled=true;try{const {error}=await cloud.auth.signOut();if(error)throw error;user=null;switchDataSpace(null);renderHome();renderSettings();$('#account-dialog').close();toast('Signed out. Guest progress is ready.');}catch(err){$('#auth-message').textContent=err.message||'Sign-out failed. Please try again.';}finally{$('#auth-signout').disabled=false;}}
